function createKendoConfirm(n,o,e){var a=$("<div />").kendoWindow({title:"Confirm",resizable:!1,draggable:!1,modal:!0,actions:[]});a.data("kendoWindow").wrapper.addClass("confirmation-wrapper"),a.data("kendoWindow").content($("#"+n).html()).center().open(),a.find(".confirm, .cancel").click(function(n){n.preventDefault(),$(this).hasClass("confirm")?"function"==typeof o&&o():"function"==typeof e&&e(),a.data("kendoWindow").close()})}